class_name OperationMechRuntime
extends Node3D

const MechControllerScript := preload("res://mech/src/mech_controller.gd")

signal asset_lost(asset_id: String)
signal metric(key: String, value)
signal threat_cue(cue: Dictionary)

const ENTER_RANGE := 5.0
const STATE_HZ := 10.0
const LOOK_SENS := 0.0021
const REMOTE_COMMAND_TIMEOUT := 0.25

var crowd: CrowdStream = null
var players_root: Node3D = null
var runtime: OperationRuntime = null
var mech: MechController = null
var _proxy: Node3D = null
var _proxy_label: Label3D = null
var _proxy_camera: Camera3D = null
var _authoritative := false
var _driver_peer := 0
var _replicated_state: Dictionary = {}
var _look_accum := Vector2.ZERO
var _remote_command: Dictionary = {}
var _remote_command_age := 999.0
var _state_acc := 0.0
var _reported_shots := 0
var _reported_rockets := 0


func setup(p_crowd: CrowdStream, p_players_root: Node3D,
		p_runtime: OperationRuntime = null) -> void:
	crowd = p_crowd
	players_root = p_players_root
	runtime = p_runtime
	_authoritative = multiplayer.is_server()
	_remote_command = ActorIface.empty_command()
	if _authoritative:
		mech = MechControllerScript.new()
		mech.name = "Mech"
		mech.position = OperationLayout.pois().mech_drop
		add_child(mech)
		mech.control_enabled = false
		mech.set_embarked(false)
		if mech.health != null:
			mech.health.destroyed.connect(_on_mech_destroyed)
		_publish_state()
	else:
		_build_proxy()


func _build_proxy() -> void:
	_proxy = Node3D.new()
	_proxy.name = "MechProxy"
	add_child(_proxy)
	var body := MeshInstance3D.new()
	var box := BoxMesh.new()
	box.size = Vector3(2.8, 3.4, 3.6)
	body.mesh = box
	body.position.y = 1.7
	var mat := StandardMaterial3D.new()
	mat.albedo_color = Color(0.25, 0.42, 0.50)
	mat.metallic = 0.5
	body.material_override = mat
	_proxy.add_child(body)
	_proxy_label = Label3D.new()
	_proxy_label.position = Vector3(0, 4.2, 0)
	_proxy_label.billboard = BaseMaterial3D.BILLBOARD_ENABLED
	_proxy_label.text = "MECH-01"
	_proxy.add_child(_proxy_label)

	# Remote driver still receives an FPS role view. Host keeps the full VS-6
	# cockpit; client uses this cheap proxy until the cockpit presentation is
	# fully replicated.
	_proxy_camera = Camera3D.new()
	_proxy_camera.name = "RemoteCockpitCamera"
	_proxy_camera.position = Vector3(0, 2.75, 0.15)
	_proxy_camera.fov = 70.0
	_proxy_camera.current = false
	_proxy.add_child(_proxy_camera)


func _physics_process(dt: float) -> void:
	if _authoritative:
		_host_physics(dt)
	else:
		_client_driver_tick(dt)


func _host_physics(dt: float) -> void:
	if mech == null:
		return
	if _driver_peer > 1:
		_remote_command_age += dt
	if _driver_peer > 0 and mech.health.state != ActorIface.ActorState.DESTROYED:
		var cmd: Dictionary = ActorIface.empty_command()
		if _driver_peer == 1:
			cmd = _poll_host_command(dt)
		elif _remote_command_age <= REMOTE_COMMAND_TIMEOUT:
			cmd = _remote_command
		var shots_before := mech.weapons.shots_fired
		var rockets_before := mech.weapons.rockets_launched
		mech.apply_command(cmd, dt)
		_resolve_packed_weapon_delta(mech.weapons.shots_fired - shots_before,
			mech.weapons.rockets_launched - rockets_before)
	_state_acc += dt
	if _state_acc >= 1.0 / STATE_HZ:
		_state_acc = 0.0
		_publish_state()


func _client_driver_tick(dt: float) -> void:
	var local_peer := multiplayer.get_unique_id()
	if _driver_peer != local_peer or local_peer <= 1:
		return
	var cmd := _poll_local_remote_command(dt)
	_submit_driver_command.rpc_id(1, cmd)


func _poll_host_command(dt: float) -> Dictionary:
	return _poll_keyboard_command(dt)


func _poll_local_remote_command(dt: float) -> Dictionary:
	return _poll_keyboard_command(dt)


func _poll_keyboard_command(dt: float) -> Dictionary:
	var mv := Vector2(
		float(Input.is_key_pressed(KEY_D)) - float(Input.is_key_pressed(KEY_A)),
		float(Input.is_key_pressed(KEY_S)) - float(Input.is_key_pressed(KEY_W))
	).limit_length(1.0)
	var look := Vector2.ZERO
	if dt > 0.0:
		look = (_look_accum * LOOK_SENS / dt).limit_length(6.0)
	_look_accum = Vector2.ZERO
	return ActorIface.make_command(
		mv, look, false,
		Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT),
		Input.is_mouse_button_pressed(MOUSE_BUTTON_RIGHT), false)


static func sanitize_driver_command(cmd: Dictionary) -> Dictionary:
	var mv := Vector2.ZERO
	var look := Vector2.ZERO
	var mv_v = cmd.get("mv", Vector2.ZERO)
	var look_v = cmd.get("look", Vector2.ZERO)
	if mv_v is Vector2:
		mv = mv_v
	if look_v is Vector2:
		look = look_v
	return ActorIface.make_command(
		mv.limit_length(1.0),
		look.limit_length(6.0),
		false,
		bool(cmd.get("fire_p", false)),
		bool(cmd.get("fire_s", false)),
		false)


func _resolve_packed_weapon_delta(rotary_shots: int, rockets: int) -> void:
	if crowd == null or mech == null:
		return
	var aim := mech.rig.aim_ray()
	var origin: Vector3 = aim.get("from", mech.global_position)
	var forward: Vector3 = aim.get("dir", -mech.global_basis.z)
	var range_mul := float(runtime.hazard_value("mech_range_mul", 1.0)) if runtime != null else 1.0
	for _shot in range(maxi(rotary_shots, 0)):
		var slot := crowd.find_enemy_in_cone_los(
			origin, forward, 90.0 * range_mul, 0.975, [mech.get_rid()])
		if slot >= 0:
			crowd.apply_damage(slot, int(round(MechWeapons.ROTARY_DMG)),
				mech, false, "mech_rotary")
	for _rocket in range(maxi(rockets, 0)):
		var slot := crowd.find_enemy_in_cone_los(
			origin, forward, 120.0 * range_mul, 0.94, [mech.get_rid()])
		if slot >= 0:
			var impact := crowd.enemy_position(slot)
			crowd.apply_damage(slot, int(round(MechWeapons.ROCKET_DMG)),
				mech, false, "mech_rocket")
			crowd.damage_in_radius(impact, MechWeapons.AOE_RADIUS,
				MechWeapons.AOE_DMG, "mech_rocket")
	if mech.weapons.shots_fired != _reported_shots:
		_reported_shots = mech.weapons.shots_fired
		metric.emit("mech_rotary_shots", _reported_shots)
	if mech.weapons.rockets_launched != _reported_rockets:
		_reported_rockets = mech.weapons.rockets_launched
		metric.emit("mech_rockets_launched", _reported_rockets)


func _unhandled_input(event: InputEvent) -> void:
	var local_peer := multiplayer.get_unique_id()
	if event is InputEventMouseMotion and _driver_peer == local_peer \
			and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		_look_accum += event.relative
	elif event is InputEventKey and event.pressed and not event.echo and event.keycode == KEY_M:
		if _authoritative:
			_host_toggle_driver(local_peer)
		else:
			_request_toggle_driver.rpc_id(1)


func _host_toggle_driver(peer_id: int) -> void:
	if mech == null or mech.health.state == ActorIface.ActorState.DESTROYED:
		return
	if _driver_peer == peer_id:
		_exit_mech()
		return
	if _driver_peer != 0:
		return
	var pilot := _pilot(peer_id)
	if pilot == null or pilot.downed or pilot.embarked \
			or pilot.global_position.distance_to(mech.global_position) > ENTER_RANGE:
		return
	_driver_peer = peer_id
	_remote_command = ActorIface.empty_command()
	_remote_command_age = 999.0
	pilot.set_embarked_state(true)
	mech.control_enabled = true
	mech.set_embarked(true)
	mech.rig.cam.current = peer_id == 1
	if peer_id == 1:
		Input.mouse_mode = Input.MOUSE_MODE_CAPTURED
	metric.emit("mech_enter", {"peer": peer_id})
	_publish_state()


func _exit_mech() -> void:
	var old_driver := _driver_peer
	var pilot := _pilot(old_driver)
	if pilot != null and mech != null:
		pilot.global_position = mech.global_position + mech.global_basis.x * 3.2 + Vector3.UP * 0.2
		pilot.set_embarked_state(false)
	_driver_peer = 0
	_remote_command = ActorIface.empty_command()
	_remote_command_age = 999.0
	if mech != null:
		mech.control_enabled = false
		mech.set_embarked(false)
		mech.rig.cam.current = false
	metric.emit("mech_exit", {"peer": old_driver})
	_publish_state()


func _force_eject() -> void:
	if _driver_peer > 0:
		_exit_mech()


func on_peer_left(peer_id: int) -> void:
	if _authoritative and _driver_peer == peer_id:
		_exit_mech()


func _pilot(peer_id: int) -> PlayerAvatar:
	if players_root == null or peer_id <= 0:
		return null
	return players_root.get_node_or_null("Player_%d" % peer_id) as PlayerAvatar


func apply_enemy_damage(amount: float, source_role: String, enemy_uid: int = -1) -> bool:
	if not _authoritative or mech == null or mech.health == null \
			or mech.health.state == ActorIface.ActorState.DESTROYED or amount <= 0.0:
		return false
	var before := mech.health.fraction()
	mech.take_damage(ActorIface.make_damage(amount, ActorIface.Source.ENEMY, enemy_uid))
	var after := mech.health.fraction()
	threat_cue.emit({"kind":"mech_hit","source_role":source_role,
		"amount":amount,"integrity_after":after,"map_pos":mech.global_position})
	metric.emit("mech_damage", {"role":source_role,"amount":amount,"hp_frac":after})
	return before > 0.0 and mech.health.state == ActorIface.ActorState.DESTROYED


func is_destroyed() -> bool:
	return mech == null or mech.health == null \
		or mech.health.state == ActorIface.ActorState.DESTROYED


func _on_mech_destroyed(_evt: Dictionary) -> void:
	_force_eject()
	asset_lost.emit("MECH_01")
	_publish_state()


func get_state() -> Dictionary:
	return _state_dict() if _authoritative else _replicated_state.duplicate(true)


func _state_dict() -> Dictionary:
	if mech == null:
		return _replicated_state.duplicate(true)
	return {"driver_peer": _driver_peer, "position": mech.position,
		"rotation": mech.rotation,
		"hp_frac": mech.health.fraction() if mech.health != null else 0.0,
		"actor_state": mech.health.state if mech.health != null else ActorIface.ActorState.DESTROYED,
		"heat": mech.weapons.heat if mech.weapons != null else 0.0,
		"rockets": mech.weapons.rockets_display() if mech.weapons != null else 0}


func _publish_state() -> void:
	var state := _state_dict()
	_replicated_state = state.duplicate(true)
	if multiplayer.multiplayer_peer != null:
		_receive_state.rpc(state)


@rpc("any_peer", "call_remote", "reliable")
func _request_toggle_driver() -> void:
	if multiplayer.is_server():
		_host_toggle_driver(multiplayer.get_remote_sender_id())


@rpc("any_peer", "call_remote", "unreliable_ordered")
func _submit_driver_command(cmd: Dictionary) -> void:
	if not multiplayer.is_server():
		return
	var sender := multiplayer.get_remote_sender_id()
	if sender <= 1 or sender != _driver_peer:
		return
	_remote_command = sanitize_driver_command(cmd)
	_remote_command_age = 0.0


@rpc("authority", "call_remote", "unreliable_ordered")
func _receive_state(state: Dictionary) -> void:
	if multiplayer.is_server():
		return
	_replicated_state = state.duplicate(true)
	_driver_peer = int(state.get("driver_peer", 0))
	if _proxy != null:
		_proxy.position = state.get("position", OperationLayout.pois().mech_drop)
		_proxy.rotation = state.get("rotation", Vector3.ZERO)
	if _proxy_label != null:
		_proxy_label.text = "MECH-01  HP %d%%" % int(float(state.get("hp_frac", 0.0)) * 100.0)
	if _proxy_camera != null:
		_proxy_camera.current = _driver_peer == multiplayer.get_unique_id()

class_name OperationNav
extends RefCounted

## Converts OperationLayout's centered world-space AABBs into the packed
## FlowField coordinate space [0..FIELD_SIZE]. One authored layout feeds
## visuals, collision and crowd navigation.

const AGENT_RADIUS := 0.6
const CORE_CLEAR_RADIUS_CELLS := 3.0


static func world_to_cell(pos: Vector3) -> Vector2i:
	var cx := int(floor((pos.x + OperationLayout.FIELD_HALF) / OperationLayout.CROWD_CELL))
	var cy := int(floor((pos.z + OperationLayout.FIELD_HALF) / OperationLayout.CROWD_CELL))
	return Vector2i(
		clampi(cx, 0, OperationLayout.GRID_W - 1),
		clampi(cy, 0, OperationLayout.GRID_H - 1)
	)


static func core_cell() -> Vector2i:
	return world_to_cell(OperationLayout.pois().core)


static func lane_cells(include_c: bool = false) -> Array[Vector2i]:
	var p := OperationLayout.pois()
	var out: Array[Vector2i] = [
		world_to_cell(p.spawn_A),
		world_to_cell(p.spawn_B),
	]
	if include_c:
		out.append(world_to_cell(p.spawn_C))
	return out


static func build_field(lane_c_open: bool = false) -> FlowField:
	var field := FlowField.new(
		OperationLayout.GRID_W,
		OperationLayout.GRID_H,
		OperationLayout.CROWD_CELL
	)
	var n := field.w * field.h
	field.blocked.resize(n)
	field.blocked.fill(0)
	field.dist.resize(n)
	field.dist.fill(-1)
	field.dir.resize(n)

	# Hard border ring.
	for x in range(field.w):
		field.blocked[x] = 1
		field.blocked[(field.h - 1) * field.w + x] = 1
	for y in range(field.h):
		field.blocked[y * field.w] = 1
		field.blocked[y * field.w + field.w - 1] = 1

	for blocker in OperationLayout.nav_blockers(lane_c_open):
		_rasterize_aabb(field, blocker)

	var goal := core_cell()
	# The visual rig occupies the goal. Keep a small attack courtyard open so
	# the wavefront has a valid goal and enemies can reach the Core ring.
	field.clear_disc(goal.x, goal.y, CORE_CLEAR_RADIUS_CELLS)
	var goals_x: Array[int] = [goal.x]
	var goals_y: Array[int] = [goal.y]
	field.rebuild(goals_x, goals_y)
	return field


static func validate(lane_c_open: bool = false) -> Dictionary:
	var field := build_field(lane_c_open)
	var p := OperationLayout.pois()
	var result := {
		"cells": field.w * field.h,
		"cell_size_m": field.cell,
		"lane_c_open": lane_c_open,
		"spawn_reachable": {},
	}
	for lane_id in ["A", "B", "C"]:
		var c := world_to_cell(p["spawn_%s" % lane_id])
		var idx := c.y * field.w + c.x
		result.spawn_reachable[lane_id] = field.dist[idx] >= 0
	return result


static func _rasterize_aabb(field: FlowField, blocker: Dictionary) -> void:
	var pos: Vector3 = blocker.pos
	var size: Vector3 = blocker.size
	var nav_padding := float(blocker.get("nav_padding", AGENT_RADIUS))
	var min_x := pos.x - size.x * 0.5 - nav_padding
	var max_x := pos.x + size.x * 0.5 + nav_padding
	var min_z := pos.z - size.z * 0.5 - nav_padding
	var max_z := pos.z + size.z * 0.5 + nav_padding

	var x0 := clampi(int(floor((min_x + OperationLayout.FIELD_HALF) / field.cell)), 1, field.w - 2)
	var x1 := clampi(int(floor((max_x + OperationLayout.FIELD_HALF) / field.cell)), 1, field.w - 2)
	var y0 := clampi(int(floor((min_z + OperationLayout.FIELD_HALF) / field.cell)), 1, field.h - 2)
	var y1 := clampi(int(floor((max_z + OperationLayout.FIELD_HALF) / field.cell)), 1, field.h - 2)

	for y in range(y0, y1 + 1):
		var row := y * field.w
		for x in range(x0, x1 + 1):
			field.blocked[row + x] = 1

class_name OperationRuntime
extends Node

const KernelScript := preload("res://mission/mission_kernel.gd")
const Defs := preload("res://mission/defs.gd")

signal mission_state_changed(state: Dictionary)
signal mission_event(event: Dictionary)
signal presentation_event(event: Dictionary)

const EXTRACTION_PAD_RADIUS := 5.0

var shell: OperationShell = null
var crowd: CrowdStream = null
var core: CoreObject = null
var players_root: Node3D = null

var kernel = KernelScript.new()
var _authoritative := false
var _configured := false
var _replicated_state: Dictionary = {}
var _batch_tokens: Dictionary = {}
var _next_batch_token := 1
var _last_core_hp := -1
var _state_broadcast_acc := 0.0
var _lane_c_open := false
var _threat_preview: Dictionary = {}
var _active_hazard := ""
var _hazard_end_step := 0
var _last_warning := ""


func setup(p_shell: OperationShell, p_crowd: CrowdStream, p_core: CoreObject,
		p_players_root: Node3D = null) -> void:
	shell = p_shell
	crowd = p_crowd
	core = p_core
	players_root = p_players_root
	_authoritative = multiplayer.is_server()
	if _authoritative:
		kernel.event_emitted.connect(_on_kernel_event)
		var cfg := MissionLoader.load_canonical()
		if cfg.is_empty():
			push_error("OperationRuntime: canonical mission config failed to load")
			return
		var accepted: Dictionary = kernel.configure(cfg)
		if not bool(accepted.get("accepted", false)):
			push_error("OperationRuntime: MissionKernel configure rejected: %s" % str(accepted))
			return
		_configured = true
		crowd.configure_role_tuning(cfg.get("roles", {}))
		core.core_hp = kernel.core_hp
		_last_core_hp = core.core_hp
		shell.set_greedy(kernel.risk_id == "GREEDY")
		_publish_state()


func _process(delta: float) -> void:
	if not _authoritative or not _configured:
		return
	kernel.advance(delta)
	_update_hazard()
	_report_core_damage()
	_resolve_cleared_batches()
	_state_broadcast_acc += delta
	if _state_broadcast_acc >= 0.2:
		_state_broadcast_acc = 0.0
		_publish_state()


func mission_config() -> Dictionary:
	return kernel.cfg.duplicate(true) if _authoritative and _configured else {}


func get_state() -> Dictionary:
	if _authoritative and _configured:
		return _state_for_replication()
	return _replicated_state.duplicate(true)


func request_start_wave() -> void:
	if _authoritative:
		_host_start_wave()
	else:
		_request_start_wave.rpc_id(1)


func request_toggle_risk() -> void:
	var current := str(get_state().get("risk_id", "SAFE"))
	request_set_risk("SAFE" if current == "GREEDY" else "GREEDY")


func request_set_risk(mode: String) -> void:
	if _authoritative:
		_host_set_risk(mode)
	else:
		_request_set_risk.rpc_id(1, mode)


func request_withdrawal() -> void:
	if _authoritative:
		_host_request_withdrawal(multiplayer.get_unique_id())
	else:
		_request_withdrawal.rpc_id(1)


func hazard_active(id: String = "") -> bool:
	if _active_hazard == "":
		return false
	return id == "" or _active_hazard == id


func hazard_value(key: String, fallback = 1.0):
	if not hazard_active() or not _configured:
		return fallback
	var spec: Dictionary = kernel.cfg.get("hazard_effects", {}).get(_active_hazard, {})
	return spec.get(key, fallback)


func report_presentation_event(kind: String, payload: Dictionary = {}) -> void:
	if not _authoritative:
		return
	var e := payload.duplicate(true)
	e["kind"] = kind
	e["step"] = int(kernel.step)
	presentation_event.emit(e)
	if multiplayer.multiplayer_peer != null:
		_receive_presentation_event.rpc(e)


func _accept_world_reports() -> bool:
	return _authoritative and _configured and kernel.phase != Defs.CONCLUDED


func report_ammo_spent(amount: int) -> void:
	if _accept_world_reports() and amount > 0:
		kernel.cmd(Defs.CMD_AMMO_SPENT, {"amount": amount})


func report_resupply(amount: int) -> void:
	if _accept_world_reports() and amount > 0:
		kernel.cmd(Defs.CMD_RESUPPLY, {"amount": amount})


func report_supply_trip(peer_id: int) -> void:
	if _accept_world_reports():
		kernel.cmd(Defs.CMD_REPORT_METRIC, {
			"key": "supply_trip", "value": {"peer": peer_id, "step": int(kernel.step)}})


func report_asset_lost(asset_id: String) -> void:
	if _accept_world_reports():
		kernel.cmd(Defs.CMD_ASSET_LOST, {"asset_id": asset_id})


func report_metric(key: String, value) -> void:
	if _accept_world_reports():
		kernel.cmd(Defs.CMD_REPORT_METRIC, {"key": key, "value": value})


func register_asset(asset_id: String, asset_type: String) -> void:
	if _authoritative and _configured:
		kernel.cmd(Defs.CMD_ASSET_REGISTERED, {"asset_id": asset_id, "type": asset_type})


func _host_start_wave() -> void:
	if not _configured:
		return
	kernel.cmd(Defs.CMD_START_WAVE)
	_publish_state()


func _host_set_risk(mode: String) -> void:
	if not _configured:
		return
	kernel.cmd(Defs.CMD_SET_RISK, {"mode": mode})
	_publish_state()


func _host_request_withdrawal(requester_peer: int) -> void:
	if not _configured:
		return
	if kernel.quota_met and not _peer_on_extraction_pad(requester_peer):
		_last_warning = "EXTRACTION REQUIRES PAD"
		report_presentation_event("extraction_denied", {
			"peer": requester_peer, "reason": "REQUIRES_PAD",
			"map_pos": OperationLayout.pois().extraction_pad})
		_publish_state()
		return
	kernel.cmd(Defs.CMD_REQUEST_WITHDRAWAL)
	_publish_state()


func _peer_on_extraction_pad(peer_id: int) -> bool:
	if players_root == null:
		return false
	var p := players_root.get_node_or_null("Player_%d" % peer_id) as Node3D
	if p == null:
		return false
	if bool(p.get("downed")) or bool(p.get("embarked")):
		return false
	return p.global_position.distance_to(OperationLayout.pois().extraction_pad) <= EXTRACTION_PAD_RADIUS


func _report_core_damage() -> void:
	if core == null:
		return
	if kernel.phase == Defs.CONCLUDED:
		_last_core_hp = core.core_hp
		return
	if _last_core_hp < 0:
		_last_core_hp = core.core_hp
		return
	if core.core_hp < _last_core_hp:
		kernel.cmd(Defs.CMD_CORE_DAMAGE, {
			"amount": _last_core_hp - core.core_hp, "source": "CROWD"})
	_last_core_hp = core.core_hp


func _resolve_cleared_batches() -> void:
	if kernel.phase == Defs.CONCLUDED or _batch_tokens.is_empty() or crowd == null:
		return
	for token_v in _batch_tokens.keys().duplicate():
		var token := int(token_v)
		if crowd.batch_present(token):
			continue
		var batch_id := str(_batch_tokens[token_v])
		_batch_tokens.erase(token_v)
		kernel.cmd(Defs.CMD_BATCH_RESOLVED, {"batch_id": batch_id})


func _on_kernel_event(e: Dictionary) -> void:
	var kind := str(e.get("kind", ""))
	match kind:
		Defs.EV_SPAWN_INTENT:
			_handle_spawn_intent(e)
		Defs.EV_WAVE_PLANNED:
			var planned_lanes: Array = e.get("lanes", [])
			if planned_lanes.has("C"):
				_open_lane_c()
		Defs.EV_THREAT_PREVIEW:
			_threat_preview = e.duplicate(true)
		Defs.EV_WAVE_STARTED:
			_threat_preview = {}
		Defs.EV_RISK:
			if shell != null:
				shell.set_greedy(str(e.get("to", "")) == "GREEDY")
		Defs.EV_HAZARD:
			_begin_hazard(str(e.get("hazard_id", "")))
		Defs.EV_CONTRACT_READY:
			_last_warning = "CONTRACT READY — EXTRACT OR CONTINUE"
			report_presentation_event("quota_met", {})
		Defs.EV_RESOLVED:
			_write_result_artifacts()
	mission_event.emit(e)
	if multiplayer.multiplayer_peer != null:
		_receive_event.rpc(e)


func _begin_hazard(id: String) -> void:
	if id == "":
		return
	var spec: Dictionary = kernel.cfg.get("hazard_effects", {}).get(id, {})
	_active_hazard = id
	_hazard_end_step = int(kernel.step) + int(spec.get("duration_steps", 50))
	_last_warning = id.replace("_", " ")
	if shell != null:
		shell.set_hazard(id)
	report_presentation_event("hazard_started", {
		"hazard_id": id, "ends_at_step": _hazard_end_step})


func _update_hazard() -> void:
	if _active_hazard == "" or int(kernel.step) < _hazard_end_step:
		return
	var ended := _active_hazard
	_active_hazard = ""
	_hazard_end_step = 0
	if shell != null:
		shell.set_hazard("")
	report_presentation_event("hazard_cleared", {"hazard_id": ended})


func _handle_spawn_intent(e: Dictionary) -> void:
	if crowd == null:
		return
	var lane_id := str(e.get("lane", ""))
	if lane_id == "C":
		_open_lane_c()
	var role_name := str(e.get("role", "PRESSURE"))
	var amount := int(e.get("count", 0))
	var aggression := float(e.get("aggression", 1.0))
	var token := _next_batch_token
	_next_batch_token += 1
	if crowd.queue_spawn_intent(lane_id, role_name, amount, aggression, token):
		_batch_tokens[token] = str(e.get("batch_id", ""))
	else:
		push_error("OperationRuntime: rejected spawn intent %s" % str(e))


func _open_lane_c() -> void:
	if _lane_c_open:
		return
	_lane_c_open = true
	if shell != null:
		shell.set_lane_c_open(true)
	if crowd != null:
		crowd.set_lane_c_open(true)


func _write_result_artifacts() -> void:
	if not _authoritative:
		return
	var log_dir := ProjectSettings.globalize_path("user://logs")
	DirAccess.make_dir_recursive_absolute(log_dir)
	kernel.telemetry.dump_jsonl("user://logs/operation_latest.jsonl")
	var f := FileAccess.open("user://logs/operation_result.json", FileAccess.WRITE)
	if f != null:
		f.store_string(JSON.stringify({
			"state": kernel.state(), "kpis": kernel.kpis(),
			"telemetry_digest": kernel.telemetry.digest()}, "\t", true))
		f.close()


func _state_for_replication() -> Dictionary:
	var state := kernel.state()
	state["threat_preview"] = _threat_preview.duplicate(true)
	state["active_hazard"] = _active_hazard
	state["hazard_end_step"] = _hazard_end_step
	state["withdrawal_end_step"] = int(kernel.withdrawal_end_step)
	state["last_warning"] = _last_warning
	state["extraction_pad"] = OperationLayout.pois().extraction_pad
	return state


func _publish_state() -> void:
	if not _configured:
		return
	var state := _state_for_replication()
	_replicated_state = state.duplicate(true)
	mission_state_changed.emit(_replicated_state)
	if multiplayer.multiplayer_peer != null:
		_receive_state.rpc(_replicated_state)


func _unhandled_input(event: InputEvent) -> void:
	if not event is InputEventKey or not event.pressed or event.echo:
		return
	match event.keycode:
		KEY_ENTER:
			request_start_wave()
		KEY_G:
			request_toggle_risk()
		KEY_E:
			request_withdrawal()


@rpc("any_peer", "call_remote", "reliable")
func _request_start_wave() -> void:
	if multiplayer.is_server():
		_host_start_wave()


@rpc("any_peer", "call_remote", "reliable")
func _request_set_risk(mode: String) -> void:
	if multiplayer.is_server():
		_host_set_risk(mode)


@rpc("any_peer", "call_remote", "reliable")
func _request_withdrawal() -> void:
	if multiplayer.is_server():
		_host_request_withdrawal(multiplayer.get_remote_sender_id())


@rpc("authority", "call_remote", "unreliable_ordered")
func _receive_state(state: Dictionary) -> void:
	if multiplayer.is_server():
		return
	_replicated_state = state.duplicate(true)
	mission_state_changed.emit(_replicated_state)


@rpc("authority", "call_remote", "reliable")
func _receive_event(e: Dictionary) -> void:
	if multiplayer.is_server():
		return
	var kind := str(e.get("kind", ""))
	if kind == Defs.EV_RISK and shell != null:
		shell.set_greedy(str(e.get("to", "")) == "GREEDY")
	elif kind == Defs.EV_WAVE_PLANNED:
		var planned_lanes: Array = e.get("lanes", [])
		if planned_lanes.has("C") and shell != null:
			_lane_c_open = true
			shell.set_lane_c_open(true)
	mission_event.emit(e)


@rpc("authority", "call_remote", "reliable")
func _receive_presentation_event(e: Dictionary) -> void:
	if multiplayer.is_server():
		return
	presentation_event.emit(e)

class_name OperationThreatRuntime
extends Node

const CombatStats := preload("res://combat/data/combat_stats.gd")

signal threat_cue(cue:Dictionary)

const HARASSER_WINDUP_SEC := 0.65

var crowd:CrowdStream=null
var players_root:Node3D=null
var mech_runtime:OperationMechRuntime=null
var runtime:OperationRuntime=null
var _cooldowns:Dictionary={}
var _windups:Dictionary={}


func setup(p_crowd:CrowdStream,p_players:Node3D,p_mech:OperationMechRuntime,
		p_runtime:OperationRuntime)->void:
	crowd=p_crowd
	players_root=p_players
	mech_runtime=p_mech
	runtime=p_runtime


func _physics_process(dt:float)->void:
	if not multiplayer.is_server() or crowd==null or not crowd.sim_mode:
		return
	for key in _cooldowns.keys().duplicate():
		_cooldowns[key]=maxf(0.0,float(_cooldowns[key])-dt)
	_tick_windups(dt)
	_attack_pilots()
	_attack_mech()


func _ready_key(key:String)->bool:
	return float(_cooldowns.get(key,0.0))<=0.0 and not _windups.has(key)


func _start_windup(key:String,target_kind:String,target_id:int,enemy_slot:int)->void:
	if enemy_slot < 0:
		return
	_windups[key]={
		"left":HARASSER_WINDUP_SEC,
		"target_kind":target_kind,
		"target_id":target_id,
		"enemy_uid":crowd.enemy_uid(enemy_slot),
	}
	threat_cue.emit({"kind":"harasser_lock","target":target_kind,
		"target_id":target_id,"enemy_uid":crowd.enemy_uid(enemy_slot)})


func _tick_windups(dt:float)->void:
	for key_v in _windups.keys().duplicate():
		var key:=str(key_v)
		var w:Dictionary=_windups[key]
		w.left=float(w.left)-dt
		if float(w.left)>0.0:
			_windups[key]=w
			continue
		_windups.erase(key)
		var uid: int = int(w.enemy_uid)
		var slot: int = -1
		if crowd.sim != null:
			slot = crowd.sim.slot_of_uid(uid)
		if slot<0:
			continue
		if str(w.target_kind)=="PILOT":
			var p:=_player(int(w.target_id))
			if p==null or p.downed or p.embarked:
				continue
			if p.global_position.distance_to(crowd.enemy_position(slot))>16.0 \
					or not crowd.world_los_clear(
						p.global_position+Vector3.UP,
						crowd.enemy_position(slot)+Vector3.UP*0.25,
						1, [p.get_rid()]):
				continue
			var dmg: float = float(CombatStats.ensure().harasser_proj_damage)
			var down: bool = p.apply_operation_damage(dmg,"HARASSER")
			_cooldowns[key]=float(CombatStats.ensure().harasser_proj_interval)
			threat_cue.emit({"kind":"pilot_down" if down else "pilot_hit",
				"peer":p.peer_id,"source_role":"HARASSER","amount":dmg,
				"map_pos":p.global_position})
			if runtime!=null:
				runtime.report_metric("pilot_damage",
					{"peer":p.peer_id,"role":"HARASSER","amount":dmg,"down":down})
		elif str(w.target_kind)=="MECH":
			if mech_runtime==null or mech_runtime.is_destroyed() or mech_runtime.mech==null:
				continue
			var pos: Vector3 = mech_runtime.mech.global_position
			if pos.distance_to(crowd.enemy_position(slot))>20.0 \
					or not crowd.world_los_clear(
						pos+Vector3.UP,
						crowd.enemy_position(slot)+Vector3.UP*0.25,
						1, [mech_runtime.mech.get_rid()]):
				continue
			mech_runtime.apply_enemy_damage(
				float(CombatStats.ensure().harasser_proj_damage),"HARASSER",uid)
			_cooldowns[key]=float(CombatStats.ensure().harasser_proj_interval)


func _player(peer_id:int)->PlayerAvatar:
	if players_root==null:
		return null
	return players_root.get_node_or_null("Player_%d"%peer_id) as PlayerAvatar


func _attack_pilots()->void:
	if players_root==null:
		return
	var stats=CombatStats.ensure()
	for n in players_root.get_children():
		var p:=n as PlayerAvatar
		if p==null or p.downed or p.embarked:
			continue
		var key:="pilot_melee_%d"%p.peer_id
		if _ready_key(key):
			var slot:=crowd.find_nearest_enemy(p.global_position,2.4,false,"HARASSER")
			if slot>=0 and crowd.world_los_clear(
					p.global_position+Vector3.UP,
					crowd.enemy_position(slot)+Vector3.UP*0.2,
					1,[p.get_rid()]):
				var role:=crowd.enemy_role(slot)
				var dmg:=float(stats.armored_melee_damage if role=="ARMORED" else stats.pressure_melee_damage)
				var interval:=float(stats.armored_melee_interval if role=="ARMORED" else stats.pressure_melee_interval)
				var down:=p.apply_operation_damage(dmg,role)
				_cooldowns[key]=interval
				threat_cue.emit({"kind":"pilot_down" if down else "pilot_hit",
					"peer":p.peer_id,"source_role":role,"amount":dmg,"map_pos":p.global_position})
				if runtime!=null:
					runtime.report_metric("pilot_damage",
						{"peer":p.peer_id,"role":role,"amount":dmg,"down":down})
		var hkey:="pilot_harasser_%d"%p.peer_id
		if _ready_key(hkey):
			var har:=crowd.find_nearest_role_enemy(
				p.global_position,16.0,"HARASSER",true,[p.get_rid()])
			if har>=0:
				_start_windup(hkey,"PILOT",p.peer_id,har)


func _attack_mech()->void:
	if mech_runtime==null or mech_runtime.mech==null or mech_runtime.is_destroyed():
		return
	var pos:Vector3=mech_runtime.mech.global_position
	if _ready_key("mech_melee"):
		var slot:=crowd.find_nearest_enemy(pos,3.4,false,"HARASSER")
		if slot>=0 and crowd.world_los_clear(
				pos+Vector3.UP,crowd.enemy_position(slot)+Vector3.UP*0.2,
				1,[mech_runtime.mech.get_rid()]):
			var role:=crowd.enemy_role(slot)
			var dmg:float=20.0 if role=="ARMORED" else 6.0
			mech_runtime.apply_enemy_damage(dmg,role,crowd.enemy_uid(slot))
			_cooldowns["mech_melee"]=1.4 if role=="ARMORED" else 1.0
	if _ready_key("mech_harasser"):
		var har:=crowd.find_nearest_role_enemy(
			pos,20.0,"HARASSER",true,[mech_runtime.mech.get_rid()])
		if har>=0:
			_start_windup("mech_harasser","MECH",0,har)

extends CharacterBody3D
class_name PlayerAvatar

const PilotPresentation := preload("res://combat/src/pilot/pilot_presentation.gd")
## Unified production pilot network root.
##
## Gameplay truth stays on the host and is rollback/reconciliation compatible.
## This node owns collision + movement state; presentation is attached separately
## and is never allowed to author gameplay transforms.
##
## Pipeline:
## peer input -> predicted rollback tick -> host authoritative state ->
## reconciliation/interpolation. Discrete fire is resolved outside rollback.

const RUN_SPEED := 7.5
const GROUND_ACCEL := 50.0
const GROUND_DECEL := 60.0
const AIR_ACCEL := 16.0
const GRAVITY := 24.0
const JUMP_SPEED := 8.4
const MAX_HP := 100
const RESPAWN_SEC := 5.0
const PILOT_FIRE_INTERVAL := 0.18
const MOUSE_LOOK_SENS := 0.0026
const MAX_PITCH := 1.25
const FREE_TURN_SPEED := 12.0
const AIM_TURN_SPEED := 22.0
const FACE_FROM_HVEL_MIN := 0.8

var peer_id := 0
var hp := MAX_HP
var downed := false
var respawn_left := 0.0
var embarked := false
var is_local_pilot := false
var drive_mode := "synthetic"    # "synthetic" | "input"
var input_enabled := true
var metrics = null

# Rollback state: consumed action sequences must reconcile together with motion.
var last_jump_seq := 0
var grounded := true

# Synthetic driver state (benchmarks / headless)
var _drive_phase := 0.0
var _drive_fire_cooldown := 0.0

# Real-input responsiveness tracking
var _press_pos := Vector3.ZERO
var _motion_pending_ms := -1
var _weapon_cooldown := 0.0
var presentation: Node3D = null
var _jump_was_down := false

@onready var pilot_input: PilotInput = $PilotInput


func setup(p_peer_id: int, p_local: bool) -> void:
	peer_id = p_peer_id
	is_local_pilot = p_local
	name = "Player_%d" % p_peer_id
	var pi := PilotInput.new()
	pi.name = "PilotInput"
	pi.set_multiplayer_authority(p_peer_id)
	add_child(pi)


func _ready() -> void:
	var col := CollisionShape3D.new()
	col.name = "PilotCollision"
	var shape := CapsuleShape3D.new()
	shape.radius = 0.42
	shape.height = 1.8
	col.shape = shape
	col.position.y = 0.9
	add_child(col)

	floor_max_angle = deg_to_rad(46.0)
	floor_snap_length = 0.4
	slide_on_ceiling = true

	presentation = PilotPresentation.new()
	presentation.name = "PilotPresentation"
	presentation.local_view = is_local_pilot and drive_mode == "input"
	add_child(presentation)
	presentation.setup(get_rid(), is_local_pilot and drive_mode == "input")
	if is_local_pilot and drive_mode == "input":
		Input.mouse_mode = Input.MOUSE_MODE_CAPTURED


func face_world_point(target: Vector3) -> void:
	var from := global_position if is_inside_tree() else position
	var flat := target - from
	flat.y = 0.0
	if flat.length_squared() <= 0.0001:
		return
	# setup() creates PilotInput before this node enters the tree, while the
	# @onready cache is populated only in _ready(). Support both call sites.
	var input_node := pilot_input
	if input_node == null:
		input_node = get_node_or_null("PilotInput") as PilotInput
	if input_node == null:
		return
	input_node.look_yaw = wrapf(atan2(-flat.x, -flat.z), -PI, PI)
	rotation.y = input_node.look_yaw


func _gather_local_input(delta: float) -> void:
	if not input_enabled or downed or embarked or not is_local_pilot or not is_inside_tree():
		if pilot_input != null and (downed or embarked):
			pilot_input.move = Vector2.ZERO
		return
	match drive_mode:
		"input":
			_gather_real_input(delta)
		_:
			_gather_synthetic_input(delta)


func _gather_synthetic_input(delta: float) -> void:
	_drive_phase += delta * PI * 0.5
	pilot_input.move = Vector2(sin(_drive_phase * 0.7), cos(_drive_phase))
	pilot_input.look_yaw += delta * 0.6
	pilot_input.look_pitch = 0.0
	pilot_input.aiming = false
	_drive_fire_cooldown -= delta
	if _drive_fire_cooldown <= 0.0:
		_drive_fire_cooldown = 1.0
		pilot_input.fire_seq += 1


func _gather_real_input(delta: float) -> void:
	if InputMap.has_action("lab_left") and InputMap.has_action("lab_right") 			and InputMap.has_action("lab_forward") and InputMap.has_action("lab_back"):
		pilot_input.move = Input.get_vector("lab_left", "lab_right", "lab_forward", "lab_back")
	else:
		pilot_input.move = Vector2(
			float(Input.is_key_pressed(KEY_D)) - float(Input.is_key_pressed(KEY_A)),
			float(Input.is_key_pressed(KEY_S)) - float(Input.is_key_pressed(KEY_W))
		).limit_length(1.0)

	var yaw_turn := 0.0
	var pitch_turn := 0.0
	if InputMap.has_action("lab_turn_right") and InputMap.has_action("lab_turn_left"):
		yaw_turn = Input.get_action_strength("lab_turn_right") - Input.get_action_strength("lab_turn_left")
	else:
		yaw_turn = float(Input.is_key_pressed(KEY_RIGHT)) - float(Input.is_key_pressed(KEY_LEFT))
		pitch_turn = float(Input.is_key_pressed(KEY_DOWN)) - float(Input.is_key_pressed(KEY_UP))
	pilot_input.look_yaw = wrapf(pilot_input.look_yaw + yaw_turn * 2.0 * delta, -PI, PI)
	pilot_input.look_pitch = clampf(
		pilot_input.look_pitch + pitch_turn * 1.6 * delta, -MAX_PITCH, MAX_PITCH)

	var jump_down := Input.is_physical_key_pressed(KEY_SPACE)
	if jump_down and not _jump_was_down:
		pilot_input.jump_seq += 1
	_jump_was_down = jump_down
	pilot_input.aiming = Input.is_mouse_button_pressed(MOUSE_BUTTON_RIGHT)

	_weapon_cooldown = maxf(0.0, _weapon_cooldown - delta)
	var fire := Input.is_action_pressed("lab_fire") if InputMap.has_action("lab_fire") 		else Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT)
	if fire and _weapon_cooldown <= 0.0:
		pilot_input.fire_seq += 1
		_weapon_cooldown = PILOT_FIRE_INTERVAL

	if OS.get_environment("LAB_INPUT_DEBUG") != "" and Engine.get_process_frames() % 60 == 0:
		print("INPDBG id=%d move=%s yaw=%.2f pitch=%.2f pos=%s vel=%s" % [
			peer_id, pilot_input.move, pilot_input.look_yaw, pilot_input.look_pitch,
			global_position, velocity])

	var moving := pilot_input.move.length_squared() > 0.01
	if moving and _motion_pending_ms < 0:
		_motion_pending_ms = Time.get_ticks_msec()
		_press_pos = global_position
	elif not moving:
		_motion_pending_ms = -1


func _unhandled_input(event: InputEvent) -> void:
	if not input_enabled or downed or embarked or not is_local_pilot or drive_mode != "input":
		return
	if event is InputEventKey and event.pressed and event.keycode == KEY_ESCAPE:
		Input.mouse_mode = Input.MOUSE_MODE_VISIBLE if Input.mouse_mode == Input.MOUSE_MODE_CAPTURED 			else Input.MOUSE_MODE_CAPTURED
		return
	if event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		pilot_input.look_yaw = wrapf(
			pilot_input.look_yaw - event.relative.x * MOUSE_LOOK_SENS, -PI, PI)
		pilot_input.look_pitch = clampf(
			pilot_input.look_pitch - event.relative.y * MOUSE_LOOK_SENS,
			-MAX_PITCH, MAX_PITCH)


func set_embarked_state(on: bool) -> void:
	embarked = on
	if is_local_pilot:
		input_enabled = not on and not downed
	if pilot_input != null and on:
		pilot_input.move = Vector2.ZERO
	_refresh_presentation_state()


func set_operation_input_enabled(enabled: bool) -> void:
	set_embarked_state(not enabled)


func apply_operation_damage(amount: float, source_role: String = "ENEMY") -> bool:
	if not multiplayer.is_server() or downed or embarked or amount <= 0.0:
		return false
	hp = maxi(0, hp - int(round(amount)))
	_emit_damage_feedback()
	if hp > 0:
		if metrics:
			metrics.count("pilot_damage_events")
		return false
	downed = true
	respawn_left = RESPAWN_SEC
	input_enabled = false
	if pilot_input != null:
		pilot_input.move = Vector2.ZERO
	if metrics:
		metrics.count("pilot_downs")
	print("EVENT pilot_down peer=%d source=%s" % [peer_id, source_role])
	_refresh_presentation_state()
	return true


func _respawn_authoritative() -> void:
	hp = MAX_HP
	downed = false
	respawn_left = 0.0
	global_position = OperationLayout.player_spawn(peer_id)
	velocity = Vector3.ZERO
	grounded = true
	if is_local_pilot and not embarked:
		input_enabled = true
	if metrics:
		metrics.count("pilot_respawns")
	_refresh_presentation_state()


func _refresh_presentation_state() -> void:
	var hidden := downed or embarked
	visible = not hidden
	collision_layer = 0 if hidden else 1
	collision_mask = 0 if hidden else 1
	if presentation != null:
		presentation.visible = not hidden
		presentation.set_local_camera_active(is_local_pilot and input_enabled and not hidden)


func _process(delta: float) -> void:
	_refresh_presentation_state()
	if is_local_pilot and (downed or embarked) and pilot_input != null:
		pilot_input.move = Vector2.ZERO
	if is_local_pilot:
		_gather_local_input(delta)
	if presentation != null and not downed and not embarked:
		presentation.sync_from_avatar(self, delta)
	if _motion_pending_ms >= 0 			and (global_position - _press_pos).length() > 0.05 and metrics:
		metrics.sample("input_to_motion_ms", float(Time.get_ticks_msec() - _motion_pending_ms))
		_motion_pending_ms = -1


func _rollback_tick(delta: float, _tick: int, _is_fresh: bool) -> void:
	if multiplayer.is_server() and downed:
		respawn_left = maxf(0.0, respawn_left - delta)
		if respawn_left <= 0.0:
			_respawn_authoritative()
	if downed or embarked:
		velocity = Vector3.ZERO
		return

	var factor := NetworkTime.physics_factor
	var wish := Vector3(pilot_input.move.x, 0.0, pilot_input.move.y) 		.rotated(Vector3.UP, pilot_input.look_yaw)
	wish = wish.normalized() if wish.length_squared() > 0.0001 else Vector3.ZERO

	var horizontal := Vector3(velocity.x, 0.0, velocity.z)
	var target := wish * RUN_SPEED * factor
	var accel := AIR_ACCEL if not grounded else (
		GROUND_ACCEL if wish != Vector3.ZERO else GROUND_DECEL)
	horizontal = horizontal.move_toward(target, accel * delta * factor)
	velocity.x = horizontal.x
	velocity.z = horizontal.z

	var jump_requested := pilot_input.jump_seq != last_jump_seq
	# Consume the input edge on the tick it arrives even while airborne.
	# Otherwise a Space press in mid-air becomes a stale auto-jump on landing.
	if jump_requested:
		last_jump_seq = pilot_input.jump_seq
	if jump_requested and grounded:
		velocity.y = JUMP_SPEED * factor
		grounded = false
	elif grounded and velocity.y < 0.0:
		velocity.y = 0.0
	else:
		velocity.y -= GRAVITY * delta * factor

	# Recover the accepted locomotion donor's facing contract without adding
	# another network field: free mode faces travel, RMB aim faces camera.
	# rotation is already rollback-synchronized, so this remains deterministic.
	var face_target := rotation.y
	var turn_speed := FREE_TURN_SPEED
	if pilot_input.aiming:
		face_target = pilot_input.look_yaw
		turn_speed = AIM_TURN_SPEED
	elif horizontal.length() > FACE_FROM_HVEL_MIN:
		face_target = wrapf(atan2(-horizontal.x, -horizontal.z), -PI, PI)
	rotation.y = wrapf(
		lerp_angle(rotation.y, face_target, minf(turn_speed * delta, 1.0)),
		-PI, PI)
	move_and_slide()
	grounded = is_on_floor()


## Authoritative fire resolution happens outside the rollback loop so events
## never re-fire during resimulation.
func resolve_fire_if_new(seen_fire_seqs: Dictionary, enemies_path: NodePath, metrics,
		range_mul: float = 1.0) -> void:
	if not multiplayer.is_server():
		return
	if seen_fire_seqs.get(peer_id, -1) == pilot_input.fire_seq:
		return
	seen_fire_seqs[peer_id] = pilot_input.fire_seq
	if pilot_input.fire_seq == 0 or downed or embarked:
		return

	var crowd := get_node_or_null(enemies_path)
	if crowd == null:
		return
	var camera_ray := _authoritative_camera_ray()
	var origin: Vector3 = camera_ray[0]
	var direction: Vector3 = camera_ray[1]
	var max_range := 80.0 * maxf(0.2, range_mul)
	var result := {
		"index": -1,
		"end": origin + direction * max_range,
		"weakpoint": false,
	}
	if crowd.has_method("raycast_enemy"):
		result = crowd.raycast_enemy(origin, direction, max_range, [get_rid()])
	else:
		var fallback_hit := _find_hit(enemies_path, range_mul)
		if fallback_hit >= 0:
			result.index = fallback_hit
			result.end = crowd.enemy_position(fallback_hit)

	var hit_index := int(result.get("index", -1))
	var weakpoint := bool(result.get("weakpoint", false))
	var end_pos: Vector3 = result.get("end", origin + direction * max_range)
	if hit_index >= 0:
		crowd.apply_damage(hit_index, 25, self, weakpoint, "pilot")
		if metrics:
			metrics.count("fire_hits")
			if weakpoint:
				metrics.count("pilot_weakpoint_hits")
	else:
		if metrics:
			metrics.count("fire_misses")
	_emit_shot_feedback(end_pos, hit_index >= 0, weakpoint)


func _authoritative_aim_direction() -> Vector3:
	var pitch := clampf(pilot_input.look_pitch, -MAX_PITCH, MAX_PITCH)
	var yaw := wrapf(pilot_input.look_yaw, -PI, PI)
	var cp := cos(pitch)
	return Vector3(-sin(yaw) * cp, sin(pitch), -cos(yaw) * cp).normalized()


func _authoritative_camera_ray() -> Array:
	# Reconstruct the exact nominal TPS camera geometry from replicated input.
	# This keeps hit authority in PlayerAvatar while matching the screen-center
	# camera ray used by the crosshair. The previous chest-origin ray was a
	# parallel ray offset by the shoulder camera and could miss close targets or
	# the Armored weakpoint even when the crosshair was centered on them.
	var pitch := clampf(pilot_input.look_pitch, -MAX_PITCH, MAX_PITCH)
	var yaw := wrapf(pilot_input.look_yaw, -PI, PI)
	var view_basis := Basis(Vector3.UP, yaw) * Basis(Vector3.RIGHT, pitch)
	var shoulder := global_position + Vector3.UP * PilotPresentation.CAMERA_PIVOT_HEIGHT \
		+ view_basis.x * PilotPresentation.CAMERA_SHOULDER_X
	var arm_length := PilotPresentation.CAMERA_AIM_LENGTH if pilot_input.aiming \
		else PilotPresentation.CAMERA_FREE_LENGTH
	var camera_origin := shoulder + view_basis.z * arm_length

	# Mirror SpringArm's collision intent on the authoritative side. A ray is
	# sufficient for this greybox slice and avoids trusting client presentation
	# transforms. Keep the same collision layer and margin as PilotPresentation.
	if is_inside_tree():
		var q := PhysicsRayQueryParameters3D.create(shoulder, camera_origin, 1, [get_rid()])
		q.collide_with_areas = false
		q.collide_with_bodies = true
		var hit := get_world_3d().direct_space_state.intersect_ray(q)
		if not hit.is_empty():
			var back_dir := shoulder.direction_to(camera_origin)
			var hit_dist := shoulder.distance_to(hit.position)
			camera_origin = shoulder + back_dir * maxf(
				0.0, hit_dist - PilotPresentation.CAMERA_MARGIN)

	return [camera_origin, (-view_basis.z).normalized()]


func _emit_shot_feedback(end_pos: Vector3, hit: bool, weakpoint: bool) -> void:
	if multiplayer.multiplayer_peer != null:
		shot_feedback.rpc(end_pos, hit, weakpoint)
	else:
		shot_feedback(end_pos, hit, weakpoint)


@rpc("authority", "call_local", "unreliable")
func shot_feedback(end_pos: Vector3, hit: bool, weakpoint: bool) -> void:
	if presentation == null:
		return
	presentation.tracer(presentation.muzzle_pos(), end_pos)
	presentation.shot_audio(hit, weakpoint)
	if is_local_pilot and hit:
		presentation.hit_feedback(weakpoint)


func _emit_damage_feedback() -> void:
	if not multiplayer.is_server():
		return
	if multiplayer.multiplayer_peer != null:
		pilot_damage_feedback.rpc()
	else:
		pilot_damage_feedback()


@rpc("authority", "call_local", "unreliable")
func pilot_damage_feedback() -> void:
	if is_local_pilot and presentation != null:
		presentation.damage_flash()


func _find_hit(enemies_path: NodePath, range_mul: float = 1.0) -> int:
	var crowd := get_node_or_null(enemies_path)
	if crowd == null:
		return -1
	var fwd := -global_transform.basis.z
	var origin := global_position + Vector3.UP * 1.25
	if crowd.has_method("find_enemy_in_cone_los"):
		return int(crowd.find_enemy_in_cone_los(
			origin, fwd, 12.0 * maxf(0.2, range_mul), 0.72, [get_rid()]))
	var best := -1
	var best_d := 12.0 * maxf(0.2, range_mul)
	for i in range(crowd.enemy_count()):
		var ep: Vector3 = crowd.enemy_position(i)
		var to_e := ep - global_position
		to_e.y = 0.0
		var d := to_e.length()
		if d > 0.001 and d < best_d and fwd.dot(to_e / d) > 0.72:
			best_d = d
			best = i
	return best

class_name OperationMinimap
extends Control

var snap:Dictionary={}


func _ready()->void:
	custom_minimum_size=Vector2(230,230)
	mouse_filter=Control.MOUSE_FILTER_IGNORE


func update_state(s:Dictionary)->void:snap=s;queue_redraw()


func _world_to_px(v:Vector2)->Vector2:
	var r:=Rect2(Vector2(12,12),size-Vector2(24,24))
	return Vector2(
		remap(v.x,-OperationLayout.FIELD_HALF,OperationLayout.FIELD_HALF,r.position.x,r.end.x),
		remap(v.y,-OperationLayout.FIELD_HALF,OperationLayout.FIELD_HALF,r.position.y,r.end.y))


func _draw()->void:
	draw_rect(Rect2(Vector2.ZERO,size),Color(0.03,0.04,0.06,0.86))
	draw_rect(Rect2(Vector2.ZERO,size),Color(0.25,0.3,0.4),false,1.0)
	var p: Dictionary = OperationLayout.pois()
	var core: Vector2 = _world_to_px(Vector2(p.core.x,p.core.z))
	for lane in ["A","B","C"]:
		var lane_def: Dictionary = OperationLayout.lanes()[lane]
		var mouth: Vector3 = lane_def.mouth
		var mp:=_world_to_px(Vector2(mouth.x,mouth.z))
		draw_line(core,mp,Color(0.5,0.55,0.62,0.35),3.0)
		var d:=float(snap.get("threat_lanes",{}).get(lane,0.0))
		if d>0.01:draw_circle(mp.lerp(core,clampf(d,0.15,0.85)),6.0+d*12.0,Color(1.0,0.2,0.25,0.25+d*0.45))
	var sup:=_world_to_px(Vector2(p.supply_point.x,p.supply_point.z))
	draw_rect(Rect2(sup-Vector2(4,4),Vector2(8,8)),Color(0.2,0.75,1.0))
	var ext:=_world_to_px(Vector2(p.extraction_pad.x,p.extraction_pad.z))
	draw_arc(ext,8.0,0,TAU,18,Color(0.95,0.8,0.18),2.0)
	var pts:=PackedVector2Array([core+Vector2(0,-8),core+Vector2(8,0),core+Vector2(0,8),core+Vector2(-8,0)])
	draw_colored_polygon(pts,Color(0.3,0.95,0.8))
	for key in ["teammate_pos","mech_pos","player_pos"]:
		var v:Vector2=snap.get(key,Vector2(-999,-999))
		if v.x<-100:continue
		var col:=Color(0.3,0.65,1.0) if key=="teammate_pos" else (
			Color(0.9,0.9,0.95) if key=="mech_pos" else Color.WHITE)
		draw_circle(_world_to_px(v),5.0,col)
	var nxt:=str(snap.get("next_threat_lane",""))
	if nxt!="":
		var lane_def: Dictionary = OperationLayout.lanes()[nxt]
		var mouth: Vector3 = lane_def.mouth
		draw_line(core,_world_to_px(Vector2(mouth.x,mouth.z)),Color(1.0,0.35,0.2),3.0)

class_name OperationPresentationAdapter
extends Node

signal snapshot_changed(snap:Dictionary)
signal gameplay_event(ename:StringName,payload:Dictionary)

var runtime:OperationRuntime=null
var crowd:CrowdStream=null
var defense:OperationDefenseRuntime=null
var mech:OperationMechRuntime=null
var players_root:Node3D=null
var _acc:=0.0
var _planned_lanes:Array=[]


func setup(p_runtime:OperationRuntime,p_crowd:CrowdStream,p_defense:OperationDefenseRuntime,
		p_mech:OperationMechRuntime,p_players:Node3D)->void:
	runtime=p_runtime;crowd=p_crowd;defense=p_defense;mech=p_mech;players_root=p_players
	if runtime!=null:
		runtime.mission_event.connect(_on_mission_event)
		runtime.presentation_event.connect(_on_presentation_event)
	push_snapshot()


func _process(delta:float)->void:
	_acc+=delta
	if _acc>=0.2:_acc=0.0;push_snapshot()


func push_snapshot()->void:
	var s:=snapshot()
	if OperationTelemetryContract.validate_snapshot(s).is_empty():snapshot_changed.emit(s)


func snapshot()->Dictionary:
	var state: Dictionary = runtime.get_state() if runtime != null else {}
	var densities: Dictionary = crowd.lane_densities() if crowd != null else {"A":0.0,"B":0.0,"C":0.0}
	var priority: String = ""
	var best: float = 0.0
	for lane in ["A","B","C"]:
		if float(densities.get(lane,0.0))>best:best=float(densities[lane]);priority=lane
	var preview:Dictionary=state.get("threat_preview",{})
	var lanes:Array=preview.get("lanes",[])
	var next_lane:=str(lanes[0]) if not lanes.is_empty() else ""
	var ds: Dictionary = defense.get_state() if defense != null else {}
	var ms: Dictionary = mech.get_state() if mech != null else {}
	var local_peer: int = multiplayer.get_unique_id() if multiplayer.multiplayer_peer != null else 1
	var player: PlayerAvatar = null
	if players_root != null:
		player = players_root.get_node_or_null("Player_%d" % local_peer) as PlayerAvatar
	var mate:PlayerAvatar=null
	if players_root!=null:
		for n in players_root.get_children():
			var p:=n as PlayerAvatar
			if p!=null and p.peer_id!=local_peer:mate=p;break
	var player_state:="on_foot"
	if player!=null:
		if player.downed:player_state="down"
		elif player.embarked:player_state="in_mech"
	var phase_map:={"SCOUT":"deploy","ASSAULT":"combat","INTERMISSION":"interwave",
		"WITHDRAWAL":"combat","CONCLUDED":"ended"}
	var supply:Dictionary=ds.get("supply",{})
	var reserve:=float(supply.get("reserve",0))
	var supply_frac:=0.0
	if not bool(supply.get("destroyed",false)):
		var reserve_frac:=clampf(reserve/800.0,0.0,1.0)
		var hp_frac:=float(supply.get("hp",0.0))/maxf(1.0,float(supply.get("hp_max",1.0)))
		supply_frac=minf(reserve_frac,hp_frac)
	var kpi:Dictionary=state.get("kpis",{})
	# MissionKernel clears the active plan before INTERMISSION, so
	# current_wave_index becomes 0 between waves. Keep the player-facing wave
	# display monotonic by falling back to waves_completed.
	var display_wave:=display_wave_index(state)
	return {
		"t":float(state.get("step",0))*0.1,
		"player_state":player_state,
		"player_hp":float(player.hp)/float(PlayerAvatar.MAX_HP) if player!=null else 1.0,
		"core_hp":float(state.get("core_hp",0))/maxf(1.0,float(state.get("core_max_hp",1))),
		"ex_current":int(state.get("ex_mex",0))/1000,
		"quota":int(state.get("quota_mex",0))/1000,
		"risk_state":str(state.get("risk_id","SAFE")).to_lower(),
		"greedy_pressure":1.0 if str(state.get("risk_id","SAFE"))=="GREEDY" else 0.25,
		"wave":display_wave,
		"waves_total":int(state.get("waves_total",3)),
		"phase":str(phase_map.get(str(state.get("phase","SCOUT")),"deploy")),
		"next_threat_lane":next_lane,"priority_threat_lane":priority,
		"threat_lanes":densities,
		"turret_ammo_state":ds.get("turrets",[]),
		"mech_state":"down" if int(ms.get("actor_state",0))==ActorIface.ActorState.DESTROYED else (
			"active" if int(ms.get("driver_peer",0))>0 else "ready"),
		"mech_integrity":float(ms.get("hp_frac",1.0)),
		"extract_available":bool(state.get("quota_met",false)),
		"extract_window_left":maxf(0.0,float(
			int(state.get("withdrawal_end_step",0))-int(state.get("step",0)))*0.1) \
			if str(state.get("phase",""))=="WITHDRAWAL" else -1.0,
		"supply_state":supply_frac,
		"player_pos":_pos2(player.global_position) if player!=null else Vector2(-999,-999),
		"teammate_pos":_pos2(mate.global_position) if mate!=null else Vector2(-999,-999),
		"mech_pos":_pos2(ms.get("position",Vector3(-999,0,-999))),
		"kpi":kpi,"result":state.get("outcome",{}),
		"active_hazard":str(state.get("active_hazard","")),
		"warning":str(state.get("last_warning","")),
	}


static func display_wave_index(state:Dictionary)->int:
	return maxi(int(state.get("current_wave_index",0)),int(state.get("waves_completed",0)))


static func wave_started_payload(planned_lanes:Array,e:Dictionary)->Dictionary:
	return {
		"lanes":planned_lanes.duplicate(),
		"wave_index":int(e.get("wave_index",0)),
		"name":str(e.get("name","")),
	}


func request_risk(state:StringName)->void:
	if runtime!=null:runtime.request_set_risk(String(state).to_upper())


func request_continue()->void:
	if runtime!=null:runtime.request_start_wave()


func _on_mission_event(e:Dictionary)->void:
	var kind:=str(e.get("kind",""))
	match kind:
		"WAVE_PLANNED":
			var planned_lanes: Array = e.get("lanes", [])
			_planned_lanes=planned_lanes.duplicate()
		"WAVE_STARTED":
			gameplay_event.emit(&"wave_started",wave_started_payload(_planned_lanes,e))
		"CORE_DAMAGED":gameplay_event.emit(&"core_damaged",e)
		"CORE_DESTROYED":gameplay_event.emit(&"core_destroyed",e)
		"RISK_CHANGED":gameplay_event.emit(&"risk_changed",{"state":str(e.get("to","SAFE")).to_lower()})
		"CONTRACT_READY":gameplay_event.emit(&"quota_met",{})
		"OPERATION_RESOLVED":
			if str(e.get("outcome",""))=="SUCCESS":
				gameplay_event.emit(&"mission_success",e)
			else:
				gameplay_event.emit(&"mission_failed",e)
	push_snapshot()


func _on_presentation_event(e:Dictionary)->void:
	gameplay_event.emit(StringName(str(e.get("kind","world_event"))),e)
	push_snapshot()


static func _pos2(v:Vector3)->Vector2:return Vector2(v.x,v.z)
